import java.io.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import org.apache.commons.text.StringSubstitutor;
import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

@WebServlet("/api/reports")
public class ReportGeneratorServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportGeneratorServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String sortCol = req.getParameter("sort");
        String format = req.getParameter("format");

        if (reportType == null || dateRange == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Template-based query construction for different report types
        Map<String, String> templateVars = new HashMap<>();
        templateVars.put("table", getTableForType(reportType));
        templateVars.put("range", dateRange);
        templateVars.put("sort", sortCol != null ? sortCol : "created_at");

        String queryTemplate = "SELECT id, name, amount, created_at FROM ${table} " +
                "WHERE created_at >= NOW() - INTERVAL '${range}' " +
                "ORDER BY ${sort} ASC LIMIT 500";

        StringSubstitutor sub = new StringSubstitutor(templateVars);
        String finalQuery = sub.replace(queryTemplate);

        log.info("Executing report query for type=" + reportType);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(finalQuery)) {

            resp.setContentType(getContentType(format));
            PrintWriter out = resp.getWriter();

            if ("csv".equals(format)) {
                out.println("id,name,amount,created_at");
                while (rs.next()) {
                    out.printf("%d,%s,%s,%s%n",
                        rs.getInt("id"),
                        escapeCsv(rs.getString("name")),
                        rs.getBigDecimal("amount"),
                        rs.getTimestamp("created_at"));
                }
            } else {
                out.println("[" );
                boolean first = true;
                while (rs.next()) {
                    if (!first) out.println(",");
                    out.printf("{\"id\":%d,\"name\":\"%s\",\"amount\":%s,\"ts\":\"%s\"}",
                        rs.getInt("id"),
                        escapeJson(rs.getString("name")),
                        rs.getBigDecimal("amount"),
                        rs.getTimestamp("created_at"));
                    first = false;
                }
                out.println("]");
            }
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private String getTableForType(String type) {
        switch (type) {
            case "sales": return "transactions";
            case "inventory": return "stock_movements";
            case "users": return "user_activity";
            default: return "transactions";
        }
    }

    private String getContentType(String format) {
        return "csv".equals(format) ? "text/csv" : "application/json";
    }

    private String escapeCsv(String val) {
        if (val == null) return "";
        if (val.contains(",") || val.contains("\"") || val.contains("\n")) {
            return "\"" + val.replace("\"", "\"\"") + "\"";
        }
        return val;
    }

    private String escapeJson(String val) {
        if (val == null) return "";
        return val.replace("\\", "\\\\").replace("\"", "\\\"");
    }
}
